INSERT INTO book_texts(file_id,organization_id,course_id,sha256,status,pages,characters,extracted_by,extracted_at) SELECT 'seed-file-m6-libro','org-demo','seed-course-mate6','323f65b5dcd3b59cb233f3102ab82e05d4a60a0133a8b2c5ebdffebc26703e2a','ready',16,4795,'seed-user-lucia','2026-10-19T18:30:00.000Z' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',1,'Matemáticas 6. Libro del estudiante. Edición de demostración para Colegio Horizonte. Este libro acompaña el sexto grado de primaria: cada tema tiene lectura, ejemplos resueltos y ejercicios para practicar en clase y en casa.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',2,'Tema 1. Polígonos regulares e irregulares. Un polígono es una figura plana cerrada formada por segmentos. Es regular cuando todos sus lados y todos sus ángulos son iguales, como el cuadrado o el hexágono de un panal; es irregular cuando no lo son. Los triángulos se clasifican por sus ángulos en rectángulo, obtusángulo y acutángulo. Los paralelogramos son rectángulos, cuadrados, romboides y rombos. Ejercicio: traza un rombo y un romboide y escribe en qué se diferencian.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',3,'Polígonos en la cultura maya. En los tejidos de Guatemala aparecen rombos, triángulos y hexágonos que se repiten. Observa un güipil: identifica los polígonos regulares e irregulares y las simetrías del diseño. La suma de los ángulos interiores de un pentágono es 540 grados y la de un hexágono es 720 grados.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',4,'Tema 2. Perímetro. El perímetro de un polígono es la suma de las longitudes de sus lados. En un polígono regular basta multiplicar la medida de un lado por el número de lados: un pentágono regular de 6 cm de lado tiene 30 cm de perímetro. Ejercicio: mide el perímetro del patio de la escuela y del terreno de la cancha.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',5,'Área de triángulos y círculos. El área de un triángulo es base por altura entre dos. La circunferencia mide dos por pi por el radio, y el área del círculo es pi por el radio al cuadrado. Ejercicio: calcula el área de una mesa redonda de 50 cm de radio y el área de un banderín triangular.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',6,'Tema 3. Sólidos geométricos. Los prismas y las pirámides tienen caras planas; los conos y los cilindros tienen una superficie curva. Cuenta en cada sólido sus caras, vértices y aristas: un prisma rectangular tiene 6 caras, 8 vértices y 12 aristas. Construye con cartón el desarrollo plano de un prisma, una pirámide, un cono y un cilindro.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',7,'Área y volumen. El área total de un prisma es la suma de las áreas de todas sus caras. El volumen de un prisma rectangular es largo por ancho por alto; el de un cilindro es el área de su base por su altura. Ejercicio: calcula cuánta agua cabe en un tinaco cilíndrico y cuánto cartón se necesita para una caja.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',8,'Tema 4. El plano cartesiano. Los números positivos y negativos representan temperaturas sobre y bajo cero. Un par ordenado (3, 2) indica una posición en el plano cartesiano: 3 en el eje horizontal y 2 en el vertical. Ejercicio: ubica en el plano los puntos de un mapa del barrio.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',9,'Tema 5. Numeración maya y romana. El sistema maya es vigesimal: usa punto, barra y concha, y cada posición vale veinte veces la anterior. Convierte cantidades del sistema decimal al vigesimal y escribe números romanos hasta M.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',10,'Tema 6. Fracciones. Para simplificar una fracción se dividen el numerador y el denominador entre el mismo número hasta su mínima expresión. Para sumar y restar fracciones con diferente denominador buscamos un denominador común. Ejercicio: en una receta se usa un medio de taza de azúcar y un tercio de taza de leche; ¿cuánto se usa en total?' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',11,'Multiplicación y división de fracciones. Para multiplicar fracciones se multiplican los numeradores entre sí y los denominadores entre sí. Para dividir, se multiplica por la fracción inversa del divisor. Ejercicio: si una cinta de tres cuartos de metro se reparte entre tres estudiantes, ¿cuánto recibe cada uno?' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',12,'Tema 7. Información en porcentajes. La información del contexto, como la población de un municipio o los resultados de un partido, se clasifica en variables cualitativas y cuantitativas. El porcentaje expresa una parte de cien: si 12 de 40 estudiantes prefieren el fútbol, el 30 por ciento lo prefiere. Interpreta los porcentajes de una noticia.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',13,'Tablas y gráficas. Una tabla de frecuencias cuenta cuántas veces aparece cada dato. Las gráficas de barras comparan cantidades y las gráficas circulares muestran partes de un todo. Ejercicio: organiza en una tabla y en una gráfica de barras los deportes favoritos del grado.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',14,'Tema 8. Promedio, mediana y moda. El promedio aritmético es la suma de los datos entre el número de datos. La moda es el dato que más se repite y la mediana es el dato del centro cuando se ordenan. Ejercicio: calcula el promedio, la moda y la mediana de las notas de un examen de 20 estudiantes.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',15,'Tema 9. Regla de tres. La regla de tres simple resuelve problemas de proporcionalidad: si 4 cuadernos cuestan 60 quetzales, 7 cuadernos cuestan 105 quetzales. Ejercicio: calcula cuántos quetzales se necesitan para comprar la refacción de todo el grado.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
INSERT INTO book_pages(file_id,page,text) SELECT 'seed-file-m6-libro',16,'Proyecto final. Diseña con tu equipo una feria escolar: dibuja el plano del lugar, calcula perímetros y áreas, organiza el presupuesto con fracciones y presenta en una gráfica las preferencias de tus compañeros.' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
